const K = 73;

function dehex(hex) {
  const len = hex.length / 2;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i += 1) {
    bytes[i] = parseInt(hex.slice(i * 2, i * 2 + 2), 16) ^ K;
  }
  return new TextDecoder().decode(bytes);
}

export function getBundledShaders() {
  const fragHex = "";
  const vertHex = "";
  return {
    fragmentShader: dehex(fragHex),
    vertexShader: dehex(vertHex)
  };
}
